chase from afar.","The represented business price is charged once per move."],"tests":["Insufficient slats or cash refuses the purchase; valid slats and payment transfer together."],"semantic_bindings":["buyer is the factory","seller is the sawmill"]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"make-leads-from-materials","version":"1","action_kind":"make-leads","rationale":"The lead maker mixes represented graphite and clay into leads; one unit of each material per lead is a conservative yield.","actor_selector":{"categories":["lead-maker"],"components":["lead_stock"]},"participants":{},"parameters":{"quantity":[1,100]},"checks":[{"label":"The lead maker has enough graphite","left":{"participant":{"name":"actor","path":"components.lead_stock.graphite"}},"op":"gte","right":{"action_field":"quantity"}},{"label":"The lead maker has enough clay","left":{"participant":{"name":"actor","path":"components.lead_stock.clay"}},"op":"gte","right":{"action_field":"quantity"}},{"label":"The lead maker makes a positive quantity","left":{"action_field":"quantity"},"op":"gt","right":{"literal":0}}],"effects":[{"participant":"actor","path":"components.lead_stock.graphite","op":"subtract","value":{"action_field":"quantity"}},{"participant":"actor","path":"components.lead_stock.clay","op":"subtract","value":{"action_field":"quantity"}},{"participant":"actor","path":"components.lead_stock.leads","op":"add","value":{"action_field":"quantity"}}],"limits":["The represented world gives no material recipe or yield; this mechanic uses one graphite and one clay per lead."],"tests":["Making leads is refused when either input is insufficient; valid production consumes both inputs and adds leads."],"semantic_bindings":["quantity is leads made"]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"buy-leads-transfer","version":"1","action_kind":"buy-leads","rationale":"The purchase law transfers leads and cash together; price is charged once per move.","