umed per pencil; paint and component usage rates are not specified."],"tests":["Assembly is refused if any ingredient is short; otherwise the ingredients are consumed and pencils added."],"semantic_bindings":["quantity is pencils assembled"]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"pack-pencil-boxes","version":"1","action_kind":"pack-pencils","rationale":"Packing consumes pencils and boxes and produces the same quantity of boxed pencils.","actor_selector":{"categories":["factory"],"components":["factory_stock"]},"participants":{},"parameters":{"quantity":[1,100]},"checks":[{"label":"The factory has enough pencils","left":{"participant":{"name":"actor","path":"components.factory_stock.pencils"}},"op":"gte","right":{"action_field":"quantity"}},{"label":"The factory has enough boxes","left":{"participant":{"name":"actor","path":"components.factory_stock.boxes"}},"op":"gte","right":{"action_field":"quantity"}},{"label":"The factory packs a positive quantity","left":{"action_field":"quantity"},"op":"gt","right":{"literal":0}}],"effects":[{"participant":"actor","path":"components.factory_stock.pencils","op":"subtract","value":{"action_field":"quantity"}},{"participant":"actor","path":"components.factory_stock.boxes","op":"subtract","value":{"action_field":"quantity"}},{"participant":"actor","path":"components.factory_stock.boxed_pencils","op":"add","value":{"action_field":"quantity"}}],"limits":["One box per unit is used because no packing capacity is represented."],"tests":["Packing is refused if pencils or boxes are insufficient; valid packing converts pencils into boxed pencils."],"semantic_bindings":["quantity is boxes packed"]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"carry-boxes-to-shop","version":"1","action_kind":"carry-boxes","rationale":"The described carrying transfers boxed pencils from the factory to the carrier; no journey state or travel time is represented.","actor_selector":{"categories":["carrier