   "kept_in": [
    {
     "component": "business",
     "field": "cash"
    }
   ]
  }
 ],
 "laws": [
  {
   "law_id": "logs-flow",
   "says": "The total number of logs changes only when cedar is cut or logs are sawn into slats.",
   "resource": "logs",
   "may_change_by": [
